exercises.solution:
function blocks(row, email, design) {
  if (row.email !== email) return false;
  if (design === 'unique-email') return true;
  if (design === 'partial-live-only') return !row.deleted;
  return false; // unique-email-deleted-at: a live row's NULL deleted_at never equals another NULL
}

export function insertConflicts(rows, email, design) {
  return rows.some((row) => blocks(row, email, design));
}

export function restoreConflicts(rows, index, design) {
  const others = rows.filter((row, i) => i !== index);
  return others.some((row) => blocks(row, rows[index].email, design));
}

