exercises.solution:
export function totalAttempts(writers, maxAttempts) {
  const rounds = Math.min(writers, maxAttempts);
  return rounds * writers - (rounds * (rounds - 1)) / 2;
}

export function failedWriters(writers, maxAttempts) {
  return Math.max(0, writers - maxAttempts);
}

