exercises.solution:
export function compatible(schema, app) {
  const names = new Set(schema.map((c) => c.name));
  const used = [...app.reads, ...app.writes];
  if (!used.every((name) => names.has(name))) return false;
  return schema.filter((c) => c.required).every((c) => app.writes.includes(c.name));
}

export function firstBrokenPhase(phases) {
  return phases.findIndex((phase) => phase.apps.some((app) => !compatible(phase.schema, app)));
}

