exercises.solution:
export function joinedRows(parents, perParentA, perParentB) {
  return parents * Math.max(perParentA, 1) * Math.max(perParentB, 1);
}

export function splitQueryRows(parents, perParentA, perParentB) {
  return parents + parents * perParentA + parents * perParentB;
}

