exercises.solution:
export function backfillSeconds(rows, batchRows, batchMs, pauseMs) {
  return (Math.ceil(rows / batchRows) * (batchMs + pauseMs)) / 1000;
}

export function replicaKeepsUp(batchRows, batchMs, pauseMs, liveRowsPerSec, replayRowsPerSec) {
  const cycleMs = batchMs + pauseMs;
  return batchRows * 1000 + liveRowsPerSec * cycleMs <= replayRowsPerSec * cycleMs;
}
